7	import type React from 'react';
8	import { useCallback, useContext, useMemo, useState } from 'react';
9	import { Box, Text } from 'ink';
10	import {
11	  PREVIEW_GEMINI_MODEL,
12	  PREVIEW_GEMINI_3_1_MODEL,
13	  PREVIEW_GEMINI_FLASH_MODEL,
14	  PREVIEW_GEMINI_MODEL_AUTO,
15	  DEFAULT_GEMINI_MODEL,
16	  DEFAULT_GEMINI_FLASH_MODEL,
17	  DEFAULT_GEMINI_FLASH_LITE_MODEL,
18	  DEFAULT_GEMINI_MODEL_AUTO,
19	  ModelSlashCommandEvent,
20	  logModelSlashCommand,
21	  getDisplayString,
22	  AuthType,
23	  PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL,
24	} from '@google/gemini-cli-core';
25	import { useKeypress } from '../hooks/useKeypress.js';
26	import { theme } from '../semantic-colors.js';
27	import { DescriptiveRadioButtonSelect } from './shared/DescriptiveRadioButtonSelect.js';
28	import { ConfigContext } from '../contexts/ConfigContext.js';
29	import { useSettings } from '../contexts/SettingsContext.js';
30	
31	interface ModelDialogProps {
32	  onClose: () => void;
33	}
34	
35	export function ModelDialog({ onClose }: ModelDialogProps): React.JSX.Element {
36	  const config = useContext(ConfigContext);
37	  const settings = useSettings();
38	  const [view, setView] = useState<'main' | 'manual'>('main');
39	  const [persistMode, setPersistMode] = useState(false);
40	
41	  // Determine the Preferred Model (read once when the dialog opens).
42	  const preferredModel = config?.getModel() || DEFAULT_GEMINI_MODEL_AUTO;
43	
44	  const shouldShowPreviewModels = config?.getHasAccessToPreviewModel();
45	  const useGemini31 = config?.getGemini31LaunchedSync?.() ?? false;
46	  const selectedAuthType = settings.merged.security.auth.selectedType;
47	  const useCustomToolModel =
48	    useGemini31 && selectedAuthType === AuthType.USE_GEMINI;
49	
50	  const manualModelSelected = useMemo(() => {
51	    const manualModels = [
52	      DEFAULT_GEMINI_MODEL,
53	      DEFAULT_GEMINI_FLASH_MODEL,
54	      DEFAULT_GEMINI_FLASH_LITE_MODEL,
55	      PREVIEW_GEMINI_MODEL,
56	      PREVIEW_GEMINI_3_1_MODEL,
57	      PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL,
58	      PREVIEW_GEMINI_FLASH_MODEL,
59	    ];
60	    if (manualModels.includes(preferredModel)) {
61	      return preferredModel;
62	    }
63	    return '';
64	  }, [preferredModel]);
65	
66	  useKeypress(
67	    (key) => {
68	      if (key.name === 'escape') {
69	        if (view === 'manual') {
70	          setView('main');
71	        } else {
72	          onClose();
73	        }
74	        return true;
75	      }
76	      if (key.name === 'tab') {
77	        setPersistMode((prev) => !prev);
78	        return true;
79	      }
80	      return false;
81	    },
82	    { isActive: true },
83	  );
84	
85	  const mainOptions = useMemo(() => {
86	    const list = [
87	      {
88	        value: DEFAULT_GEMINI_MODEL_AUTO,
89	        title: getDisplayString(DEFAULT_GEMINI_MODEL_AUTO),
90	        description:
91	          'Let Gemini CLI decide the best model for the task: gemini-2.5-pro, gemini-2.5-flash',
92	        key: DEFAULT_GEMINI_MODEL_AUTO,
93	      },
94	      {
95	        value: 'Manual',
96	        title: manualModelSelected
97	          ? `Manual (${getDisplayString(manualModelSelected)})`
98	          : 'Manual',
99	        description: 'Manually select a model',
100	        key: 'Manual',
101	      },
102	    ];
103	
104	    if (shouldShowPreviewModels) {
105	      list.unshift({
106	        value: PREVIEW_GEMINI_MODEL_AUTO,
107	        title: getDisplayString(PREVIEW_GEMINI_MODEL_AUTO),
108	        description: useGemini31
109	          ? 'Let Gemini CLI decide the best model for the task: gemini-3.1-pro, gemini-3-flash'
110	          : 'Let Gemini CLI decide the best model for the task: gemini-3-pro, gemini-3-flash',
111	        key: PREVIEW_GEMINI_MODEL_AUTO,
112	      });
113	    }
114	    return list;
115	  }, [shouldShowPreviewModels, manualModelSelected, useGemini31]);
116	
117	  const manualOptions = useMemo(() => {
118	    const list = [
119	      {
120	        value: DEFAULT_GEMINI_MODEL,
121	        title: getDisplayString(DEFAULT_GEMINI_MODEL),
122	        key: DEFAULT_GEMINI_MODEL,
123	      },
124	      {
125	        value: DEFAULT_GEMINI_FLASH_MODEL,
126	        title: getDisplayString(DEFAULT_GEMINI_FLASH_MODEL),
127	        key: DEFAULT_GEMINI_FLASH_MODEL,
128	      },
129	      {
130	        value: DEFAULT_GEMINI_FLASH_LITE_MODEL,
131	        title: getDisplayString(DEFAULT_GEMINI_FLASH_LITE_MODEL),
132	        key: DEFAULT_GEMINI_FLASH_LITE_MODEL,
133	      },
134	    ];
135	
136	    if (shouldShowPreviewModels) {
137	      const previewProModel = useGemini31
138	        ? PREVIEW_GEMINI_3_1_MODEL
139	        : PREVIEW_GEMINI_MODEL;
140	
141	      const previewProValue = useCustomToolModel
142	        ? PREVIEW_GEMINI_3_1_CUSTOM_TOOLS_MODEL
143	        : previewProModel;
144	
145	      list.unshift(
146	        {
147	          value: previewProValue,
148	          title: getDisplayString(previewProModel),
149	          key: previewProModel,
150	        },
151	        {
152	          value: PREVIEW_GEMINI_FLASH_MODEL,
153	          title: getDisplayString(PREVIEW_GEMINI_FLASH_MODEL),
154	          key: PREVIEW_GEMINI_FLASH_MODEL,
155	        },
156	      );
157	    }
158	    return list;
159	  }, [shouldShowPreviewModels, useGemini31, useCustomToolModel]);
160	
161	  const options = view === 'main' ? mainOptions : manualOptions;
162	
163	  // Calculate the initial index based on the preferred model.
164	  const initialIndex = useMemo(() => {
165	    const idx = options.findIndex((option) => option.value === preferredModel);
166	    if (idx !== -1) {
167	      return idx;
168	    }
169	    if (view === 'main') {
170	      const manualIdx = options.findIndex((o) => o.value === 'Manual');
171	      return manualIdx !== -1 ? manualIdx : 0;
172	    }
173	    return 0;
174	  }, [preferredModel, options, view]);
175	
176	  // Handle selection internally (Autonomous Dialog).
177	  const handleSelect = useCallback(
178	    (model: string) => {
179	      if (model === 'Manual') {
180	        setView('manual');
181	        return;
182	      }
183	
184	      if (config) {
185	        config.setModel(model, persistMode ? false : true);
186	        const event = new ModelSlashCommandEvent(model);
187	        logModelSlashCommand(config, event);
188	      }
189	      onClose();
190	    },
191	    [config, onClose, persistMode],
192	  );
193	
194	  return (
195	    <Box
196	      borderStyle="round"
197	      borderColor={theme.border.default}
198	      flexDirection="column"
199	      padding={1}
200	      width="100%"
201	    >
202	      <Text bold>Select Model</Text>
203	
204	      <Box marginTop={1}>
205	        <DescriptiveRadioButtonSelect
206	          items={options}
207	          onSelect={handleSelect}
208	          initialIndex={initialIndex}
209	          showNumbers={true}
210	        />
211	      </Box>
212	      <Box marginTop={1} flexDirection="column">
213	        <Box>
214	          <Text color={theme.text.primary}>
215	            Remember model for future sessions:{' '}
216	          </Text>
217	          <Text color={theme.status.success}>
218	            {persistMode ? 'true' : 'false'}
219	          </Text>
220	        </Box>
221	        <Text color={theme.text.secondary}>(Press Tab to toggle)</Text>
222	      </Box>
223	      <Box marginTop={1} flexDirection="column">
224	        <Text color={theme.text.secondary}>
225	          {'> To use a specific Gemini model on startup, use the --model flag.'}
226	        </Text>
227	      </Box>
228	      <Box marginTop={1} flexDirection="column">
229	        <Text color={theme.text.secondary}>(Press Esc to close)</Text>
230	      </Box>
231	    </Box>
232	  );
233	}
